AtRule(node) {
  if (
    /-?keyframes$/.test(node.name) &&
    !node.params.endsWith(`-${shortId}`)
  ) {
    // register keyframes
    keyframes[node.params] = node.params = node.params + '-' + shortId
  } else if (isNestedInRule(node)) {
    // wrap declarations in nested at-rules with `&` so that they can be
    // scoped like nested rules. e.g. `.foo { @media { color: red } }`
    const nodes = node.nodes
    if (nodes) {
      const decls = nodes.filter(
        child => child.type === 'decl' || child.type === 'comment',
      )
      if (decls.length) {
        for (const decl of decls) {
          node.removeChild(decl)
        }
        node.prepend(new Rule({ nodes: decls, selector: '&' }))
      }
    }
  }
},

