function isNestedInRule(node: AtRule) {
  let parent = node.parent
  while (parent) {
    if (parent.type === 'rule') {
      return true
    }
    if (parent.type === 'root') {
      return false
    }
    parent = parent.parent
  }
  return false
}

function isSpaceCombinator(node: selectorParser.Node) {
  return node.type === 'combinator' && /^\s+$/.test(node.value)
}

